// 手繪風插畫：胖胖的角色＋套印錯位（紅版偏移）＋粗糙邊（#rough 濾鏡，在 layout 的 <SvgDefs/>）
import { useId, type ReactNode } from "react";

const B = "#8B421F"; // 焦棕
const M = "#F5AD00"; // 芥末黃
const G = "#FFBE16"; // 金橘
const C = "#FFFBE9"; // 奶油
const R = "#E64B2E"; // 朱紅
const K = "#5A2A12"; // 深棕

type ArtProps = { className?: string; title?: string };

/** 共用外框：先畫一層偏移的紅色剪影（套印錯位），再畫本體 */
function Art({ vb, children, className, title, misreg = true, rough = true }: ArtProps & { vb: string; children: ReactNode; misreg?: boolean; rough?: boolean }) {
  return (
    <svg
      viewBox={vb}
      className={className}
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      overflow="visible"
    >
      {misreg && (
        <g transform="translate(6 5)" filter="url(#misreg)" opacity="0.9">
          {children}
        </g>
      )}
      <g filter={rough ? "url(#rough)" : undefined}>{children}</g>
    </svg>
  );
}

const Face = ({ x, y, gap = 34, color = C, blush = true, size = 1 }: { x: number; y: number; gap?: number; color?: string; blush?: boolean; size?: number }) => (
  <g>
    <circle cx={x - gap / 2} cy={y} r={6.5 * size} fill={color} />
    <circle cx={x + gap / 2} cy={y} r={6.5 * size} fill={color} />
    <path d={`M${x - 11 * size} ${y + 13 * size} Q${x} ${y + 25 * size} ${x + 11 * size} ${y + 13 * size}`} stroke={color} strokeWidth={6 * size} fill="none" strokeLinecap="round" />
    {blush && (
      <>
        <circle cx={x - gap / 2 - 14 * size} cy={y + 13 * size} r={7 * size} fill={R} opacity="0.9" />
        <circle cx={x + gap / 2 + 14 * size} cy={y + 13 * size} r={7 * size} fill={R} opacity="0.9" />
      </>
    )}
  </g>
);

