/* ---------------- 裝飾 ---------------- */

const starPoints = (n: number, R1: number, r: number, cx: number, cy: number, jitter: number[]) =>
  Array.from({ length: n * 2 }, (_, i) => {
    const rad = (i % 2 ? r : R1) * (1 + (jitter[i % jitter.length] ?? 0));
    const a = (Math.PI / n) * i - Math.PI / 2;
    return `${(cx + Math.cos(a) * rad).toFixed(1)},${(cy + Math.sin(a) * rad).toFixed(1)}`;
  }).join(" ");

export function Star({ className, color = G }: { className?: string; color?: string }) {
  return (
    <svg viewBox="0 0 100 100" className={className} aria-hidden="true" overflow="visible">
      <polygon points={starPoints(5, 46, 20, 50, 52, [0.02, -0.06, 0.05, 0.04, -0.04, 0.08, -0.03, 0.02, 0.06, -0.05])} fill={color} stroke={B} strokeWidth="5" strokeLinejoin="round" filter="url(#rough)" />
    </svg>
  );
}

export function Sparkle({ className, color = R }: { className?: string; color?: string }) {
  return (
    <svg viewBox="0 0 100 100" className={className} aria-hidden="true">
      <path d="M50 4C54 38 62 46 96 50 62 54 54 62 50 96 46 62 38 54 4 50 38 46 46 38 50 4z" fill={color} filter="url(#rough)" />
    </svg>
  );
}

export function Squiggle({ className, color = R }: { className?: string; color?: string }) {
  return (
    <svg viewBox="0 0 120 40" className={className} aria-hidden="true" overflow="visible">
      <path d="M6 30C16 6 26 6 32 22s18 16 24 0 18-16 24 0 18 16 34-8" stroke={color} strokeWidth="9" fill="none" strokeLinecap="round" filter="url(#rough)" />
    </svg>
  );
}

export function Confetti({ className }: { className?: string }) {
  const bits: [number, number, number, string, "r" | "z" | "c"][] = [
    [20, 30, -20, R, "r"], [80, 12, 30, G, "z"], [150, 40, 10, B, "c"], [210, 18, -30, R, "z"],
    [260, 46, 40, M, "r"], [40, 90, 20, M, "z"], [120, 80, -40, R, "c"], [190, 96, 15, B, "r"], [250, 110, -15, G, "c"],
  ];
  return (
    <svg viewBox="0 0 280 130" className={className} aria-hidden="true" overflow="visible">
      {bits.map(([x, y, rot, c, t], i) => (
        <g key={i} transform={`translate(${x} ${y}) rotate(${rot})`} className="confetti-bit" style={{ animationDelay: `${i * -0.37}s` }}>
          {t === "r" && <rect x="-9" y="-4" width="18" height="8" rx="2" fill={c} />}
          {t === "c" && <circle r="6" fill={c} />}
          {t === "z" && <path d="M-12 0l6-6 6 6 6-6 6 6" stroke={c} strokeWidth="5" fill="none" strokeLinecap="round" strokeLinejoin="round" />}
        </g>
      ))}
    </svg>
  );
}

/** 手繪箭頭：data-draw 讓捲動時「畫」出來 */
export function Arrow({ className, color = R, flip = false }: { className?: string; color?: string; flip?: boolean }) {
  return (
    <svg viewBox="0 0 160 110" className={className} aria-hidden="true" overflow="visible" style={flip ? { transform: "scaleX(-1)" } : undefined}>
      <g filter="url(#rough)" fill="none" stroke={color} strokeWidth="7" strokeLinecap="round" strokeLinejoin="round">
        <path data-draw d="M8 18C40 4 76 10 88 34c10 20-8 36-22 26-12-9 2-30 26-26 24 4 42 26 50 54" />
        <path data-draw d="M128 74l14 16 6-22" />
      </g>
    </svg>
  );
}

/** 爆炸星形徽章 */
export function Burst({ className, color = R, children }: { className?: string; color?: string; children?: ReactNode }) {
  return (
    <div className={className} style={{ position: "relative", display: "grid", placeItems: "center" }}>
      <svg viewBox="0 0 200 200" style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }} aria-hidden="true" className="spin-slow">
        <polygon points={starPoints(16, 98, 80, 100, 100, [0.02, -0.03, 0.01, 0.03, -0.02])} fill={color} stroke={B} strokeWidth="4" strokeLinejoin="round" filter="url(#rough)" />
      </svg>
      <div style={{ position: "relative", textAlign: "center" }}>{children}</div>
    </div>
  );
}

/** 圓環文字徽章（會慢慢轉） */
export function RingText({ text, className, children, color = B }: { text: string; className?: string; children?: ReactNode; color?: string }) {
  const id = useId().replace(/:/g, "");
  return (
    <div className={className} style={{ position: "relative", display: "grid", placeItems: "center" }}>
      <svg viewBox="0 0 200 200" style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }} aria-hidden="true" className="spin-slow">
        <defs>
          <path id={`ring-${id}`} d="M100 100m-78 0a78 78 0 1 1 156 0a78 78 0 1 1-156 0" />
        </defs>
        <text fontFamily={`"Noto Sans TC", "PingFang TC", "Microsoft JhengHei", sans-serif`} fontWeight="900" fontSize="16" letterSpacing="2" fill={color}>
          <textPath href={`#ring-${id}`} textLength="486" lengthAdjust="spacing">{text}</textPath>
        </text>
      </svg>
      <div style={{ position: "relative" }}>{children}</div>
    </div>
  );
}

/** 不規則色塊背景（手撕紙邊），preserveAspectRatio=none 會隨容器延展 */
export function TornPanel({ color = M, seed = 1, className }: { color?: string; seed?: number; className?: string }) {
  let s = seed * 9301 + 49297;
  const rnd = () => ((s = (s * 9301 + 49297) % 233280) / 233280);
  const pts: string[] = [];
  const j = () => (rnd() - 0.5) * 14;
  for (let x = 0; x <= 1000; x += 40) pts.push(`${x},${8 + j()}`);
  for (let y = 0; y <= 1000; y += 40) pts.push(`${992 + j()},${y}`);
  for (let x = 1000; x >= 0; x -= 40) pts.push(`${x},${992 + j()}`);
  for (let y = 1000; y >= 0; y -= 40) pts.push(`${8 + j()},${y}`);
  return (
    <svg viewBox="0 0 1000 1000" preserveAspectRatio="none" className={className} aria-hidden="true">
      <polygon points={pts.join(" ")} fill={color} />
    </svg>
  );
}

/** 波浪分隔線 */
export function Wave({ color = M, className, flip = false }: { color?: string; className?: string; flip?: boolean }) {
  return (
    <svg viewBox="0 0 1440 60" preserveAspectRatio="none" className={className} aria-hidden="true" style={{ display: "block", width: "100%", height: "clamp(28px,4vw,60px)", transform: flip ? "scaleY(-1)" : undefined }}>
      <path d="M0 60V30C60 8 120 8 180 28s120 22 180 2 120-22 180-2 120 22 180 2 120-22 180-2 120 22 180 2 120-22 180-2 120 22 180 2V60z" fill={color} />
    </svg>
  );
}

/** 依活動挑插畫（沒有照片時用） */
const BY_SLUG: Record<string, (p: ArtProps) => ReactNode> = {
  painting: Pencil, swim: Sun, artshow: Flower, concert: Drum, dance: Dragon, singapore: Globe,
};
export function ActArt({ slug, cat, className }: { slug: string; cat: string; className?: string }) {
  const Cmp = BY_SLUG[slug] ?? (cat === "慶祝" ? Cake : cat === "傳承" ? Book : Globe);
  return <Cmp className={className} />;
}
